std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> dis(0.0, 1.0);

vec3 totalVelocity(0, 0, 0);
double totalMass = 0.0;

for (size_t i = 0; i < velocities.size(); ++i) {
    double vx = dis(gen) * std::sqrt(temperature / masses[i]);
    double vy = dis(gen) * std::sqrt(temperature / masses[i]);
    double vz = dis(gen) * std::sqrt(temperature / masses[i]);
    velocities[i] = vec3(vx, vy, vz);
    totalVelocity += velocities[i] * masses[i];
    totalMass += masses[i];
}

totalVelocity /= totalMass;

for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] -= totalVelocity;
}

